"use client"

/**
 * Clean-room forgot-password card.
 * The sent state is the same sentence for every address. Rejections never
 * render the host error, so the card cannot say whether an account exists.
 */

import { useId, useState, type FormEvent } from "react"

import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { cn } from "@/lib/utils"
import { forgotCopy, recoverySentBody, type AuthLocale } from "./auth-recovery-copy"
import { AuthRecoveryFrame, AuthRecoveryLink, type AuthBrand } from "./auth-recovery-frame"

export type ForgotPasswordPhase = "idle" | "invalid" | "submitting" | "sent" | "error"

export type ForgotPasswordLabels = Partial<ReturnType<typeof forgotCopy>>

export type ForgotPasswordClassNames = {
  root?: string
  form?: string
}

export type ForgotPasswordProps = {
  onSubmit: (email: string) => Promise<void>
  brand?: AuthBrand
  signInHref?: string
  labels?: ForgotPasswordLabels
  locale?: AuthLocale
  defaultEmail?: string
  /** Locked scene. Omit it and the card moves on its own. */
  phase?: ForgotPasswordPhase
  className?: string
  classNames?: ForgotPasswordClassNames
}

const isEmail = (value: string) => /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(value.trim())

export function ForgotPassword({
  onSubmit,
  brand,
  signInHref = "#",
  labels,
  locale = "en",
  defaultEmail = "",
  phase,
  className,
  classNames,
}: ForgotPasswordProps) {
  const copy = { ...forgotCopy(locale), ...labels }
  const sentBody = labels?.sentBody ?? recoverySentBody(locale)
  const emailId = useId()
  const errorId = useId()
  const [email, setEmail] = useState(defaultEmail)
  const [internal, setInternal] = useState<ForgotPasswordPhase>("idle")
  const [tried, setTried] = useState(false)
  const current = phase ?? internal
  const submitting = current === "submitting"
  const sent = current === "sent"
  const showFieldError = current === "invalid" || tried
  const problem = !email.trim() ? copy.emailRequired : !isEmail(email) ? copy.emailInvalid : ""
  const fieldError = showFieldError && !sent && current !== "error" ? problem : ""
  const server = current === "error"

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    if (submitting || sent || phase) return
    setTried(true)
    if (problem) {
      document.getElementById(emailId)?.focus()
      return
    }
    setInternal("submitting")
    try {
      await onSubmit(email.trim())
      setInternal("sent")
    } catch {
      setInternal("error")
    }
  }

  return (
    <AuthRecoveryFrame
      slot="forgot-password"
      phase={current}
      title={sent ? copy.sentTitle : copy.title}
      description={sent ? sentBody : copy.description}
      status={sent ? copy.sentTitle : submitting ? copy.sending : ""}
      brand={brand}
      className={cn(className, classNames?.root)}
    >
      {sent ? (
        <>
          {email.trim() ? <p className="text-sm break-all text-foreground">{email.trim()}</p> : null}
          <AuthRecoveryLink href={signInHref}>{copy.back}</AuthRecoveryLink>
        </>
      ) : (
        <>
          <form className={cn("grid gap-4", classNames?.form)} onSubmit={(event) => void submit(event)} noValidate>
            <div className="grid min-w-0 gap-2">
              <Label htmlFor={emailId}>{copy.email}</Label>
              <Input
                id={emailId}
                className="min-h-11"
                type="email"
                name="email"
                inputMode="email"
                autoComplete="email"
                autoCapitalize="none"
                spellCheck={false}
                placeholder={copy.emailPlaceholder}
                value={email}
                readOnly={submitting}
                aria-invalid={fieldError ? true : undefined}
                aria-describedby={fieldError ? errorId : undefined}
                onChange={(event) => {
                  setEmail(event.target.value)
                  if (internal === "error") setInternal("idle")
                }}
              />
              {fieldError ? (
                <p id={errorId} role="alert" className="text-xs break-all text-destructive">
                  {fieldError}
                </p>
              ) : null}
            </div>
            {server ? (
              <p role="alert" className="text-sm text-destructive">
                {copy.serverError}
              </p>
            ) : null}
            <Button type="submit" className="min-h-11 w-full" disabled={submitting} aria-busy={submitting || undefined}>
              {submitting ? copy.sending : copy.submit}
            </Button>
          </form>
          <AuthRecoveryLink href={signInHref}>{copy.back}</AuthRecoveryLink>
        </>
      )}
    </AuthRecoveryFrame>
  )
}

"use client"

/** Clean-room chrome for the recovery cards. No theme of its own. */

import { useEffect, useId, useRef, type ReactNode } from "react"
import { motion, useReducedMotionConfig } from "motion/react"

import { Card } from "@/components/ui/card"
import { cn } from "@/lib/utils"
import { motionPresets } from "@/lib/motion"

export type AuthBrand = { name: string; mark?: ReactNode }

export function AuthRecoveryLink({ href, children }: { href: string; children: ReactNode }) {
  return (
    <a
      href={href}
      className="inline-flex min-h-11 items-center self-start text-sm font-medium text-foreground underline-offset-4 hover:underline focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:outline-none"
    >
      {children}
    </a>
  )
}

export function AuthRecoveryFrame({
  slot,
  title,
  description,
  status,
  brand,
  phase,
  className,
  children,
}: {
  slot: string
  title: string
  description?: string
  status?: string
  brand?: AuthBrand
  phase: string
  className?: string
  children: ReactNode
}) {
  const reduce = useReducedMotionConfig() ?? false
  const titleId = useId()
  const headingRef = useRef<HTMLHeadingElement>(null)
  const focusTitle = phase === "sent" || phase === "success" || phase === "invalid-link" || phase === "expired"

  useEffect(() => {
    if (focusTitle) headingRef.current?.focus()
  }, [focusTitle, phase, title])

  return (
    <Card
      data-slot={slot}
      data-phase={phase}
      data-motion={reduce ? "reduced" : "full"}
      role="region"
      aria-labelledby={titleId}
      className={cn("@container w-full min-w-0 max-w-md gap-0 overflow-hidden py-0", className)}
    >
      <div className="grid min-w-0 gap-5 p-6 @max-[380px]:p-5">
        {brand ? (
          <p className="inline-flex min-w-0 items-center gap-2 text-sm font-medium">
            {brand.mark ? <span aria-hidden="true">{brand.mark}</span> : null}
            <span className="truncate">{brand.name}</span>
          </p>
        ) : null}
        <motion.div
          key={phase}
          className="grid min-w-0 gap-5"
          initial={reduce ? { opacity: 0 } : { opacity: 0, y: 12 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: reduce ? 0 : motionPresets.duration.standard, ease: [...motionPresets.ease.enter] }}
        >
          <div className="grid gap-1">
            <h2 id={titleId} ref={headingRef} tabIndex={-1} className="text-xl font-medium text-balance outline-none @min-[380px]:text-2xl">
              {title}
            </h2>
            {description ? <p className="text-sm text-pretty text-muted-foreground">{description}</p> : null}
          </div>
          {children}
        </motion.div>
      </div>
      <p className="sr-only" role="status">
        {status}
      </p>
    </Card>
  )
}

/**
 * Timing presets for pieces adapted from Arc UI (MIT).
 * Durations and springs only. No colors, fonts, or theme tokens.
 */
export const motionPresets = {
  duration: {
    instant: 0.12,
    fast: 0.16,
    exit: 0.18,
    standard: 0.24,
    considered: 0.48,
  },
  ease: {
    enter: [0.16, 1, 0.3, 1] as const,
    // Exit decelerates, the same curve as CSS ease-out.
    exit: [0, 0, 0.58, 1] as const,
    standard: [0.22, 1, 0.36, 1] as const,
    inOut: [0.65, 0, 0.35, 1] as const,
  },
  spring: {
    responsive: { type: "spring" as const, stiffness: 520, damping: 38 },
    gentle: { type: "spring" as const, stiffness: 340, damping: 34 },
    snappy: { type: "spring" as const, visualDuration: 0.26, bounce: 0.12 },
    smooth: { type: "spring" as const, visualDuration: 0.4, bounce: 0 },
    morph: { type: "spring" as const, visualDuration: 0.42, bounce: 0.16 },
  },
  stagger: { char: 0.016, word: 0.04, line: 0.08, item: 0.035 },
  blur: { subtle: 2, soft: 4, text: 8 },
}
